const TAU=Math.PI*2;
function dot(c,x,y,r,color){c.beginPath();c.arc(x,y,r,0,TAU);c.fillStyle=color;c.fill()}
function star(c,count,outer,inner,angle,color){c.beginPath();for(let i=0;i<count*2;i++){const a=angle+i*Math.PI/count,r=i%2?inner:outer;c.lineTo(Math.cos(a)*r,Math.sin(a)*r)}c.closePath();c.fillStyle=color;c.fill();c.strokeStyle='#e2d6ef';c.lineWidth=1.5;c.stroke()}
export function drawEncounter(c,e,t){const r=e.r;if(e.type!==6&&e.type<7)return false;c.save();
 if(e.type===6){const p=e.phase||1,colors=['#8dcaff','#cd9dff','#ff648d'],color=colors[p-1];const glow=c.createRadialGradient(0,0,10,0,0,r*2);glow.addColorStop(0,color+'88');glow.addColorStop(1,color+'00');dot(c,0,0,r*2,glow);
  if(p===1){star(c,6,r,r*.8,t*.3,'#243956');c.strokeStyle=color;c.lineWidth=4;for(let i=0;i<3;i++){c.save();c.rotate(t*.5+i*TAU/3);c.beginPath();c.ellipse(0,0,r*1.3,r*.55,0,0,TAU);c.stroke();c.restore()}dot(c,0,0,r*.45,'#b9edff');dot(c,0,0,r*.2,'#142c49')}
  else if(p===2){c.strokeStyle='#e4ccff';c.lineWidth=4;c.beginPath();c.moveTo(-r*.6,0);for(let i=1;i<8;i++)c.lineTo(-r*.6+i*r*1.2/8,Math.sin(i*3+t*20)*12);c.lineTo(r*.6,0);c.stroke();for(const s of [-1,1]){const y=Math.sin(t*3)*r*.25*s;dot(c,s*r*.62,y,r*.58,'#513768');star(c,5,r*.33,r*.15,t*s, '#edc9ff');dot(c,s*r*.62,y,r*.22,'#f4e8ff')}c.strokeStyle=color;c.setLineDash([7,9]);c.beginPath();c.arc(0,0,r*1.45,t,-t+TAU);c.stroke()}
  else{star(c,12,r*1.35,r*.65,-t*.55,'#602743');star(c,6,r*.8,r*.5,t*.9,'#b53f70');dot(c,0,0,r*.48,'#160f24');for(const s of [-1,1]){c.save();c.translate(s*r*.2,-r*.1);c.rotate(s*-.35);c.fillStyle='#ffe2de';c.fillRect(-r*.16,-4,r*.32,8);c.restore()}dot(c,0,r*.18,7,'#ff648d');c.strokeStyle='#ff719b';c.lineWidth=3;c.beginPath();c.arc(0,0,r*1.6,-t,-t+TAU*.75);c.stroke()}
  if(e.phaseGrace>0){c.font='bold 15px sans-serif';c.textAlign='center';c.fillStyle='#fff0f9';c.fillText('蜕变中',0,-r-40)}if(e.dashWarning>0&&e.dashTarget){const a=Math.atan2(e.dashTarget.y-e.y,e.dashTarget.x-e.x);c.rotate(a);c.strokeStyle='#ff719b';c.lineWidth=4;c.setLineDash([10,7]);c.beginPath();c.moveTo(0,0);c.lineTo(310,0);c.stroke()}
 }else if(e.type===7){dot(c,0,0,r,'#ce865b');for(let i=0;i<6;i++){const a=t+i*TAU/6;dot(c,Math.cos(a)*r,Math.sin(a)*r,5,'#ffc78c')}dot(c,0,-2,r*.45,'#763e32');dot(c,-4,-4,3,'#ffe4a5');dot(c,4,-4,3,'#ffe4a5')}
 else if(e.type===8){if(e.ionWindup>0){c.save();c.rotate(e.ionAim);c.strokeStyle='#e7c4ff';c.lineWidth=1.5;c.setLineDash([7,8]);for(const a of[-.38,0,.38]){c.save();c.rotate(a);c.beginPath();c.moveTo(r+3,0);c.lineTo(338,0);c.stroke();c.restore()}c.setLineDash([]);c.beginPath();c.arc(0,0,r+7,-Math.PI/2,-Math.PI/2+TAU*(1-e.ionWindup/e.ionWindupTotal));c.stroke();c.restore()}star(c,4,r,r*.45,t*.5,'#9273cd');for(let i=0;i<3;i++){const a=t*3+i*TAU/3;dot(c,Math.cos(a)*r*1.3,Math.sin(a)*r*.8,4,'#e7c5ff')}dot(c,0,0,5,'#f5e9ff')}
 else if(e.type===9){for(let i=0;i<3;i++){c.save();c.translate((i-1)*r*.6,Math.sin(t*5+i)*4);c.rotate((i-1)*.5);c.fillStyle=['#7ca879','#add486','#8cbe6a'][i];c.fillRect(-r*.35,-r*.8,r*.7,r*1.6);c.strokeStyle='#d2e5a7';c.strokeRect(-r*.35,-r*.8,r*.7,r*1.6);dot(c,0,-4,3,'#243a28');c.restore()}}
 else if(e.type===10){star(c,5,r*1.2,r*.5,t*.4,'#5a93ab99');dot(c,0,0,r*.7,'#b2e6ee88');dot(c,0,-3,5,'#132e3d');c.strokeStyle='#b5efff';c.setLineDash([4,6]);c.beginPath();c.arc(0,0,r*1.5,0,TAU);c.stroke();if(e.teleportWarning>0){c.font='bold 11px sans-serif';c.fillStyle='#d5f5ff';c.fillText('闪现',-12,-r-16)}}
 else if(e.type===11){star(c,7,r*1.2,r*.55,-t,'#bf6caa');dot(c,0,0,r*.35,'#f5bddf');for(let i=0;i<4;i++){const a=t*2+i*TAU/4;dot(c,Math.cos(a)*r*1.35,Math.sin(a)*r*1.35,3,'#ffd8ee')}}
 c.restore();return true;
}
export function drawFireRing(c,z,time){c.save();c.globalAlpha=Math.min(1,z.life*2);c.strokeStyle='#7c9aff77';c.lineWidth=35;c.beginPath();c.arc(z.x,z.y,z.radius,0,TAU);c.stroke();c.strokeStyle='#d9efff';c.lineWidth=4;c.beginPath();c.arc(z.x,z.y,z.radius,0,TAU);c.stroke();for(let i=0;i<44;i++){const a=i*TAU/44,x=z.x+Math.cos(a)*z.radius,y=z.y+Math.sin(a)*z.radius,h=18+Math.sin(time*15+i*2)*10;c.fillStyle=i%3?'#91b9ffbb':'#e3f8ffee';c.beginPath();c.moveTo(x-6,y+5);c.quadraticCurveTo(x-9,y-h*.4,x+Math.sin(time*9+i)*7,y-h);c.quadraticCurveTo(x+10,y-h*.3,x+6,y+5);c.fill()}c.restore()}
